"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

type Slogan = [en: string, ko: string];

const ROW_A: Slogan[] = [
  ["POETRY IS CONCRETE", "시는 콘크리트"],
  ["WORDS ARE WALLS", "단어가 벽"],
  ["WALLS ARE POEMS", "벽이 시"],
];

const ROW_B: Slogan[] = [
  ["EVERY LINE IS 3PX", "모든 선은 3픽셀"],
  ["NO GRADIENT", "그라데이션 없음"],
  ["DO NOT DEMOLISH", "무너뜨리지 마라"],
];

/** 기본 표류 속도 px/ms (~52 px/s). 고정 상수; 스크롤 연결 없음. */
const SPEED = 0.052;

/** offset 을 (-w, 0] 에 두어 복제 그룹이 매끄럽게 이어지도록. */
function wrap(v: number, w: number): number {
  const r = v % w;
  return r > 0 ? r - w : r;
}

function Row({
  items,
  mod,
  trackRef,
  groupRef,
}: {
  items: Slogan[];
  mod: "a" | "b";
  trackRef: React.RefObject<HTMLDivElement | null>;
  groupRef: React.RefObject<HTMLSpanElement | null>;
}) {
  return (
    <div className={`bk-marquee__row bk-marquee__row--${mod}`} aria-hidden="true">
      <div className="bk-marquee__track" ref={trackRef}>
        {[0, 1, 2, 3].map((n) => (
          <span
            key={n}
            className="bk-marquee__group"
            ref={n === 0 ? groupRef : undefined}
          >
            {items.map(([en, ko], i) => (
              <span key={i} className="bk-marquee__item">
                <span className="bk-marquee__en">{en}</span>{" "}
                <span lang="ko" className="bk-marquee__ko">
                  {ko}
                </span>
                <span className="bk-marquee__sep" aria-hidden="true">
                  ▮
                </span>
              </span>
            ))}
          </span>
        ))}
      </div>
    </div>
  );
}

/**
 * 섹션 사이의 슬로건 밴드 — 출판의 voice ticker. 두 줄이 반대 방향으로
 * 일정한 속도로 흐른다; 출판의 선언이 움직이는 활자. 동작 감소: 두 줄 다
 * 멈춘다.
 *
 * 움직이는 줄은 aria-hidden; 모든 슬로건은 그 앞의 visually-hidden
 * 단락에 한 번 전달된다.
 */
export default function ManifestoMarquee() {
  const reduced = usePrefersReducedMotion();
  const bandRef = useRef<HTMLDivElement | null>(null);
  const trackA = useRef<HTMLDivElement | null>(null);
  const trackB = useRef<HTMLDivElement | null>(null);
  const groupA = useRef<HTMLSpanElement | null>(null);
  const groupB = useRef<HTMLSpanElement | null>(null);

  useEffect(() => {
    const band = bandRef.current;
    const ta = trackA.current;
    const tb = trackB.current;
    const ga = groupA.current;
    const gb = groupB.current;
    if (!band || !ta || !tb || !ga || !gb) return;

    if (reduced) {
      ta.style.transform = "";
      tb.style.transform = "";
      return;
    }

    let raf = 0;
    let last = 0;
    let offA = 0;
    let offB = 0;
    let wA = Math.max(1, ga.offsetWidth);
    let wB = Math.max(1, gb.offsetWidth);

    const ro = new ResizeObserver(() => {
      wA = Math.max(1, ga.offsetWidth);
      wB = Math.max(1, gb.offsetWidth);
    });
    ro.observe(ga);
    ro.observe(gb);

    const tick = (t: number) => {
      const dt = last ? Math.min(48, t - last) : 16.7;
      last = t;
      offA = wrap(offA - SPEED * dt, wA);
      offB = wrap(offB + SPEED * dt, wB);
      ta.style.transform = `translate3d(${offA.toFixed(2)}px, 0, 0)`;
      tb.style.transform = `translate3d(${offB.toFixed(2)}px, 0, 0)`;
      raf = requestAnimationFrame(tick);
    };

    const io = new IntersectionObserver(
      ([hit]) => {
        if (hit.isIntersecting && !raf) {
          last = 0;
          raf = requestAnimationFrame(tick);
        } else if (!hit.isIntersecting && raf) {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      },
      { rootMargin: "80px" },
    );
    io.observe(band);

    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
      ro.disconnect();
    };
  }, [reduced]);

  return (
    <div className="bk-marquee" ref={bandRef}>
      <p className="bk-vh">
        {[...ROW_A, ...ROW_B].map(([en, ko]) => `${en} ${ko}`).join(" · ")}
      </p>
      <Row items={ROW_A} mod="a" trackRef={trackA} groupRef={groupA} />
      <Row items={ROW_B} mod="b" trackRef={trackB} groupRef={groupB} />
    </div>
  );
}

"use client";

/**
 * BLOCK 도형 라이브러리 — 순수 인라인 SVG, 이미지 없음.
 * 네 가지 기하 형태가 시를 상징한다: 네모(square), 세모(triangle),
 * 동그라미(circle), 쌓기(stack), 선(line), 격자(grid). 모두 잉크(#171717)
 * 외곽선 + 콘크리트 바탕이며, neo-brutalist 규칙대로 외곽선은 언제나 3px.
 *
 * 결정론적 — Math.random 없음, SSR과 클라이언트가 동일.
 */

/** 한 변의 네모 — 벽돌. 시 01(구조). */
export function Square({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 64 64"
      width="64"
      height="64"
      focusable="false"
      aria-hidden="true"
    >
      <rect
        x="6"
        y="6"
        width="52"
        height="52"
        fill="none"
        stroke="currentColor"
        strokeWidth="3"
      />
      <rect x="6" y="6" width="26" height="26" fill="currentColor" />
    </svg>
  );
}

/** 정삼각형 — 직각의 대척점, 날카로움. 시 07(방법론). */
export function Triangle({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 64 64"
      width="64"
      height="64"
      focusable="false"
      aria-hidden="true"
    >
      <polygon
        points="32,6 58,56 6,56"
        fill="none"
        stroke="currentColor"
        strokeWidth="3"
        strokeLinejoin="miter"
      />
      <polygon points="32,20 48,48 16,48" fill="currentColor" />
    </svg>
  );
}

/** 원 — 모서리가 없는 유일한 형태, 무게. 시 08(재료). */
export function Circle({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 64 64"
      width="64"
      height="64"
      focusable="false"
      aria-hidden="true"
    >
      <circle
        cx="32"
        cy="32"
        r="26"
        fill="none"
        stroke="currentColor"
        strokeWidth="3"
      />
      <circle cx="32" cy="32" r="11" fill="currentColor" />
    </svg>
  );
}

/** 쌓은 벽돌 — 층이 쌓이는 구조. 시 02, 05(태도/재료). */
export function Stack({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 64 64"
      width="64"
      height="64"
      focusable="false"
      aria-hidden="true"
    >
      <g fill="none" stroke="currentColor" strokeWidth="3">
        <rect x="8" y="10" width="48" height="12" />
        <rect x="8" y="26" width="48" height="12" />
        <rect x="8" y="42" width="48" height="12" />
      </g>
      <g fill="currentColor">
        <rect x="8" y="10" width="24" height="12" />
        <rect x="32" y="26" width="24" height="12" />
        <rect x="8" y="42" width="24" height="12" />
      </g>
    </svg>
  );
}

/** 가로선 3개 — 3px의 법칙. 시 04(방법론). */
export function Line({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 64 64"
      width="64"
      height="64"
      focusable="false"
      aria-hidden="true"
    >
      <g stroke="currentColor" strokeWidth="6" strokeLinecap="butt">
        <line x1="8" y1="16" x2="56" y2="16" />
        <line x1="8" y1="32" x2="56" y2="32" />
        <line x1="8" y1="48" x2="56" y2="48" />
      </g>
    </svg>
  );
}

/** 격자 — 문장이 된 도형들. 시 06(구조). */
export function Grid({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 64 64"
      width="64"
      height="64"
      focusable="false"
      aria-hidden="true"
    >
      <g fill="none" stroke="currentColor" strokeWidth="3">
        <rect x="8" y="8" width="48" height="48" />
        <line x1="8" y1="24" x2="56" y2="24" />
        <line x1="8" y1="40" x2="56" y2="40" />
        <line x1="24" y1="8" x2="24" y2="56" />
        <line x1="40" y1="8" x2="40" y2="56" />
      </g>
      <g fill="currentColor">
        <rect x="8" y="8" width="16" height="16" />
        <rect x="40" y="24" width="16" height="16" />
        <rect x="24" y="40" width="16" height="16" />
      </g>
    </svg>
  );
}

/** motif 문자 → 컴포넌트. PoemFlipGrid에서 쓴다. */
export function Motif({
  motif,
  className,
}: {
  motif: "square" | "triangle" | "circle" | "stack" | "line" | "grid";
  className?: string;
}) {
  switch (motif) {
    case "triangle":
      return <Triangle className={className} />;
    case "circle":
      return <Circle className={className} />;
    case "stack":
      return <Stack className={className} />;
    case "line":
      return <Line className={className} />;
    case "grid":
      return <Grid className={className} />;
    default:
      return <Square className={className} />;
  }
}

"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import { POEMS, FILTERS, LABELS, type Category, type Poem } from "./poems";
import { Motif } from "./Motifs";

type Filter = Category | "all";

/**
 * 섹션 02 (서명) — 시 그리드가 필터에서 FLIP 재배열된다. 카테고리를
 * 고르면 보이는 카드의 순서가 바뀐다; DOM 이 바뀌기 전에 각 카드의
 * bounding rect 를 찍고(First), 바뀐 뒤 새 rect 를 재고(Last), 역델타를
 * transform 으로 붙인 뒤(Invert) 0 으로 애니메이션한다(Play) — 그래서
 * 카드가 새 자리로 미끄러진다. 나가는 카드는 먼저 fade out, 들어오는
 * 카드는 같은 창에서 fade in.
 *
 * 그리드는 언제나 진짜 리스트(<ul>/<li>); 필터는 어떤 시가 렌더되는가만
 * 바꾼다 — 의미는 살아있다. 각 카드는 focusable. 동작 감소: FLIP 애니메이션
 * 없음 — 그리드가 즉시 바뀐다 (play 단계 생략, 카드가 제자리에 나타남).
 *
 * 카드는 neo-brutalist hard offset shadow(6px 6px 0) 를 단다. hover 시
 * translate(-3px,-3px) + shadow 확대(9px 9px 0, green). 누르면 spring
 * overshoot — transform 이 ease-back(0.34,1.56,0.64,1) 로 튀어오른다.
 */
export default function PoemFlipGrid() {
  const reduced = usePrefersReducedMotion();
  const [filter, setFilter] = useState<Filter>("all");
  const gridRef = useRef<HTMLUListElement | null>(null);
  /** 마지막 렌더 시작 시점의 활성 필터 — FLIP 을 구동한다. */
  const prevFilter = useRef<Filter>(filter);

  const visible: Poem[] = POEMS.filter(
    (p) => filter === "all" || p.category === filter,
  );

  // useLayoutEffect 로 First/Last 를 DOM 업데이트가 페인트되는 같은
  // 프레임에 재측정 — unmoved 카드의 깜빡임 없음.
  useLayoutEffect(() => {
    const grid = gridRef.current;
    if (!grid) return;
    if (prevFilter.current === filter) {
      prevFilter.current = filter;
      return;
    }
    prevFilter.current = filter;

    // 동작 감소: 남은 FLIP transform 만 지우고 끝.
    if (reduced) {
      for (const li of Array.from(
        grid.querySelectorAll<HTMLElement>(".bk-tile"),
      )) {
        li.style.transform = "";
        li.style.transition = "";
      }
      return;
    }

    // --- FLIP ---
    // First: 현재 rect 를 찍는다 (OLD 위치 — React 의 swap 이 페인트되기
    // 전에, layout effect 에서 돌기 때문).
    const tiles = Array.from(grid.querySelectorAll<HTMLElement>(".bk-tile"));
    const first = new Map<string, DOMRect>();
    for (const li of tiles) {
      const key = li.dataset.flipKey;
      if (key) first.set(key, li.getBoundingClientRect());
    }

    // DOM 은 이미 React 가 업데이트했다 (Last = 현재 layout).
    // OLD 위치를 아는 모든 카드에 Invert + Play.
    const PLAY_MS = 480;
    const movers: Array<{ el: HTMLElement; dx: number; dy: number }> = [];
    for (const li of Array.from(
      grid.querySelectorAll<HTMLElement>(".bk-tile"),
    )) {
      const key = li.dataset.flipKey;
      if (!key) continue;
      const old = first.get(key);
      if (!old) continue; // 새 카드 → CSS 로 fade in, FLIP 없음
      const now = li.getBoundingClientRect();
      const dx = old.left - now.left;
      const dy = old.top - now.top;
      if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) continue;
      movers.push({ el: li, dx, dy });
    }

    if (movers.length === 0) return;

    // Invert: 각 mover 를 OLD 위치에 transition 없이 놓는다.
    for (const { el, dx, dy } of movers) {
      el.style.transition = "none";
      el.style.transform = `translate3d(${dx}px, ${dy}px, 0)`;
    }
    // 강제 reflow — play transition 이 붙기 전에 inverted transform 이
    // 확정되도록.
    void grid.getBoundingClientRect();

    // Play: identity 로 transition.
    for (const { el } of movers) {
      el.style.transition = `transform ${PLAY_MS}ms cubic-bezier(0.22,1,0.36,1)`;
      el.style.transform = "";
    }
    // inline transition 이 settle 되면 지운다 — hover/tap 과 다음 FLIP 이
    // stale rule 과 싸우지 않도록.
    const cleanup = () => {
      for (const { el } of movers) {
        el.style.transition = "";
        el.style.transform = "";
      }
      grid.removeEventListener("transitionend", cleanup);
    };
    window.setTimeout(cleanup, PLAY_MS + 40);
  }, [filter, reduced]);

  // 동작 감소 설정이 런타임에 바뀌면 inline FLIP style 을 지운다.
  useEffect(() => {
    if (!reduced) return;
    const grid = gridRef.current;
    if (!grid) return;
    for (const li of Array.from(grid.querySelectorAll<HTMLElement>(".bk-tile"))) {
      li.style.transform = "";
      li.style.transition = "";
    }
  }, [reduced]);

  const count = visible.length;

  return (
    <section
      id="bk-works"
      className="bk-section bk-works"
      aria-labelledby="bk-works-title"
    >
      <div className="bk-sec">
        <span className="bk-sec__no" aria-hidden="true">
          02
        </span>
        <h2 className="bk-sec__title" id="bk-works-title">
          <span lang="ko">시</span>
          <span className="bk-sec__title-en">the poems</span>
        </h2>
      </div>

      <p className="bk-works__lede">
        <span lang="ko">
          필터를 고르면 그리드가 FLIP 으로 미끄러져 자리를 바꿉니다 — 여덟
          편의 시가 한 권의 콘크리트.
        </span>
      </p>

      <div
        className="bk-filters"
        role="group"
        aria-label={LABELS.filterLabel}
      >
        {FILTERS.map((f) => {
          const active = filter === f.id;
          return (
            <button
              key={f.id}
              type="button"
              className={`bk-filter bk-btn--press${active ? " is-active" : ""}`}
              aria-pressed={active}
              onClick={() => setFilter(f.id)}
            >
              <span lang="ko">{f.ko}</span>
              <span className="bk-filter__en">{f.en}</span>
            </button>
          );
        })}
      </div>

      <ul className="bk-grid" ref={gridRef}>
        {visible.map((p, i) => (
          <li
            key={p.id}
            data-flip-key={p.id}
            className={`bk-tile bk-tile--${p.category}`}
            tabIndex={0}
            aria-label={`${p.no}. ${p.titleKo} — ${p.tagKo}. ${p.titleEn}.`}
            style={{ ["--bk-tile-i" as string]: i }}
          >
            <div className="bk-tile__motif" aria-hidden="true">
              <Motif motif={p.motif} className="bk-tile__motif-svg" />
            </div>
            <div className="bk-tile__top">
              <span className="bk-tile__no">{p.no}</span>
              <span className="bk-tile__tag" lang="ko">
                {p.tagKo}
              </span>
            </div>
            <h3 className="bk-tile__title">
              <span lang="ko" className="bk-tile__ko">
                {p.titleKo}
              </span>
              <span className="bk-tile__en">{p.titleEn}</span>
            </h3>
            <div className="bk-tile__body">
              <p className="bk-tile__ko-body" lang="ko">
                {p.ko.map((line, j) => (
                  <span key={j} className="bk-tile__line">
                    {line}
                  </span>
                ))}
              </p>
              <p className="bk-tile__en-body">
                {p.en.map((line, j) => (
                  <span key={j} className="bk-tile__line">
                    {line}
                  </span>
                ))}
              </p>
            </div>
            <div className="bk-tile__foot">
              <span className="bk-tile__year">{p.year}</span>
              <span className="bk-tile__cat" aria-hidden="true">
                {p.motif}
              </span>
            </div>
          </li>
        ))}
      </ul>

      <p className="bk-works__caption">
        <span lang="ko">{LABELS.caption}</span>{" "}
        {LABELS.captionEn}
        <span className="bk-works__count">
          {" "}
          — <span lang="ko">보이는 시</span> {count}/08
        </span>
      </p>
    </section>
  );
}

/**
 * BLOCK — 시 데이터. 여덟 편의 짧은 시가 이 출판의 전부다.
 * 각 시는 콘크리트라는 단일 재료를 한 가지 방식으로 다룬다: 구조, 태도,
 * 재료, 방법론. 네 가지 카테고리는 FLIP 그리드의 필터가 된다.
 *
 * 한국어 2-3행이 원문이고 영문은 그 복각. motif는 시를 상징하는 기하학적
 * 형태 — 모두 CSS로 그린다 (이미지 없음).
 */

export type Category = "structure" | "attitude" | "material" | "method";

export type Motif = "square" | "triangle" | "circle" | "stack" | "line" | "grid";

export type Poem = {
  id: string;
  no: string;
  titleKo: string;
  titleEn: string;
  /** 원문 — 한국어 2-3행 */
  ko: string[];
  /** 영문 복각 */
  en: string[];
  category: Category;
  /** 시를 상징하는 기하 형태 */
  motif: Motif;
  /** 한 줄 태그 (필터 카드 위) */
  tagKo: string;
  tagEn: string;
  year: string;
};

export const POEMS: Poem[] = [
  {
    id: "poem-01",
    no: "01",
    titleKo: "시는 콘크리트다",
    titleEn: "Poetry Is Concrete",
    ko: ["단어가 벽이 되고,", "벽이 시가 된다."],
    en: ["Words become walls,", "and walls become poems."],
    category: "structure",
    motif: "square",
    tagKo: "구조",
    tagEn: "Structure",
    year: "2026",
  },
  {
    id: "poem-02",
    no: "02",
    titleKo: "무너뜨리지 마라",
    titleEn: "Do Not Demolish",
    ko: ["벽 속에 목소리가 있다.", "부수지 마라 — 들어라."],
    en: ["A voice lives inside the wall.", "Do not break it — listen."],
    category: "attitude",
    motif: "stack",
    tagKo: "태도",
    tagEn: "Attitude",
    year: "2026",
  },
  {
    id: "poem-03",
    no: "03",
